(function(root){
'use strict';
root.createPatientInvitation=function(ctx){
 const {$,esc,toast}=ctx,C=root.InvitationCore;let stayId=null,draft={},photoUrl='',rawText='',readLines=[],busy=false,linkData=null,formDraft={},generation=0,brevo=null,sending=false;
 const options=(rows,v)=>rows.map(([id,label])=>`<option value="${esc(id)}" ${id===v?'selected':''}>${esc(label)}</option>`).join('');
 const field=(name,label,type='text',value='')=>`<label>${label}<input name="${name}" type="${type}" value="${esc(value)}" ${['firstName','lastName','birthDate'].includes(name)?'required':''} maxlength="180"></label>`;
 function clearPhoto(){if(photoUrl)URL.revokeObjectURL(photoUrl);photoUrl='';rawText='';readLines=[];generation++}
 function render(){if(stayId===null)stayId=ctx.current()?.id||'';$('#title').textContent='Questionnaire depuis une photo';$('#stats').hidden=true;$('#new').hidden=true;document.querySelectorAll('.nav[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view==='questionnaireSend'));$('#workspace').innerHTML='<section class="panel"><div class="content" id="invitation-workspace"></div></section>';draw();loadStatus()}
 async function loadStatus(){try{const r=await fetch('/api/workspace/messaging/status');brevo=await r.json()}catch{brevo={ready:false,message:'État de Brevo indisponible.'}}const form=$('#invitation-contact');if(form)draw()}
 const autoChannels=c=>[...(c.phone&&brevo?.sms?.ok?['sms']:[]),...(c.email&&brevo?.email?.ok?['email']:[])];
 function brevoNotice(){if(!brevo)return '<p class="muted" id="brevo-state">Vérification de l’envoi Brevo…</p>';if(brevo.ready)return `<p class="notice ok" id="brevo-state">Envoi automatique prêt : ${[brevo.sms?.ok?'SMS ('+esc(String(brevo.sms.credits))+' crédits)':'',brevo.email?.ok?'e-mail':''].filter(Boolean).join(' et ')}.${brevo.recette?' Serveur de test : les messages sont marqués [TEST].':''}${[brevo.sms?.error,brevo.email?.error].filter(Boolean).map(x=>' '+esc(x)).join('')}</p>`;return `<p class="notice warn" id="brevo-state">Envoi automatique indisponible : ${esc(brevo.message||[brevo.sms?.error,brevo.email?.error].filter(Boolean).join(' '))} Le lien sera préparé pour être copié.</p>`}
 function draw(){const host=$('#invitation-workspace');if(!host)return;const teams=ctx.teams();const saved=ctx.patients.find(p=>p.id===stayId)?.invitationContact?.contact||{};const v={...saved,...draft,...formDraft};
 host.innerHTML=`<p class="eyebrow">PRÉPARER LE QUESTIONNAIRE PATIENT</p><h2>Photo du profil Doctolib</h2><p>Importez une photo ou une capture, puis vérifiez l’identité et le destinataire avant de préparer le message. L’image est lue dans ce navigateur et n’est pas enregistrée sur le serveur.</p><p class="notice warn">Prototype : profils fictifs uniquement. Le lien patient permet de remplir uniquement le questionnaire invité, sans compte professionnel. L’envoi par SMS ou e-mail (Brevo) ne part qu’après votre clic, vers les coordonnées vérifiées du séjour.</p><div class="invitation-grid"><section><h3>Photo à lire</h3><label class="invitation-upload">Choisir une photo ou capture<input id="doctolib-photo" type="file" accept="image/jpeg,image/png,image/webp" ${busy?'disabled':''}></label><label class="invitation-upload">Prendre une photo<input id="doctolib-camera" type="file" accept="image/jpeg,image/png,image/webp" capture="environment" ${busy?'disabled':''}></label><p class="muted">JPEG, PNG ou WebP, 12 Mo maximum. Vous pouvez aussi coller une capture dans cette zone. Une capture d’écran est plus fiable qu’une photo ; pour une photo, cadrez la fiche du patient, de face, sans reflet.</p><div id="doctolib-paste" tabindex="0" class="invitation-preview">${photoUrl?`<img src="${esc(photoUrl)}" alt="Photo du profil à comparer aux champs extraits">`:'La photo apparaîtra ici.'}</div><div class="actions"><button type="button" class="secondary" id="doctolib-read" ${!photoUrl||busy?'disabled':''}>Lire la photo</button><button type="button" class="secondary" id="doctolib-clear" ${busy?'disabled':''}>Effacer la photo</button></div><p id="doctolib-progress" role="status">${busy?'Lecture en cours…':''}</p>${readLines.length?`<details class="invitation-lines" ${!draft.lastName||!draft.firstName||!draft.birthDate?'open':''}><summary>Texte lu : touchez une ligne pour remplir un champ</summary><p class="muted">Si un champ est vide ou mal lu, choisissez la ligne correspondante puis le champ. Vérifiez toujours sur la photo.</p><ul>${readLines.map((l,i)=>`<li><span>${esc(l)}</span><span class="invitation-line-actions"><button type="button" class="secondary" data-line="${i}" data-field="lastName">Nom</button><button type="button" class="secondary" data-line="${i}" data-field="firstName">Prénom</button><button type="button" class="secondary" data-line="${i}" data-field="birthDate">Naissance</button></span></li>`).join('')}</ul></details>`:''}</section><section><h3>Vérifier l’identité et les coordonnées</h3><form id="invitation-contact"><div class="formgrid"><label class="wide">Séjour destinataire<select name="stay">${options([['','Créer un nouveau séjour fictif'],...ctx.patients.map(p=>[p.id,p.id+' · '+[p.identity?.lastName,p.identity?.firstName].filter(Boolean).join(' ')])],stayId)}</select></label>${!stayId?`<label class="wide">Équipe du nouveau séjour<select name="team" required>${options([['','Choisir une équipe'],...teams.map(t=>[t.id,t.label])],v.team||'')}</select></label>`:''}${field('lastName','Nom de naissance','text',v.lastName)}${field('firstName','Premier prénom','text',v.firstName)}${draft.usedName&&draft.usedName!==v.lastName?`<p class="notice wide"><span>Nom d’usage lu sur la photo : <strong>${esc(draft.usedName)}</strong>. L’identité utilise le nom de naissance ; vérifiez-le sur la photo.</span></p>`:''}${draft.lastNameSource==='usage'&&draft.lastName===v.lastName?'<p class="notice warn wide"><span>Nom de naissance vide ou illisible sur la fiche : le « Nom utilisé » a été repris. Vérifiez le nom de naissance sur une pièce d’identité.</span></p>':''}${draft.birthDateUnreadable&&!v.birthDate?'<p class="notice warn wide"><span>Date de naissance illisible (l’âge chevauche l’année sur la fiche) : saisissez-la.</span></p>':''}${draft.lastNameSource==='entete'&&draft.lastName===v.lastName&&!draft.usedName?'<p class="notice warn wide"><span>Nom lu dans l’en-tête de la fiche : ce peut être le nom d’usage. Vérifiez le nom de naissance (« née … ») avant de valider.</span></p>':''}${rawText&&(!draft.lastName||!draft.firstName)?'<p class="notice warn wide"><span>Nom ou prénom non reconnu : recopiez-les depuis la photo.</span></p>':''}${field('birthDate','Date de naissance','date',v.birthDate)}${field('email','E-mail du destinataire','email',v.email)}${field('phone','Téléphone du destinataire','tel',v.phone)}</div><p class="muted">Une photo ne garantit ni l’identité ni l’exactitude des coordonnées. Complétez les champs manquants et corrigez les caractères mal lus.</p><label class="check"><input name="confirmed" type="checkbox" required> J’ai vérifié la photo, l’identité du séjour et les coordonnées du destinataire.</label>${brevoNotice()}<p class="invitation-error" role="alert"></p><button class="primary" ${busy||sending||!ctx.canPrepare()?'disabled':''}>${brevo?.ready?'Envoyer le questionnaire au patient':'Préparer le lien et le message'}</button></form></section></div><section id="invitation-result" aria-live="polite"></section>`;
 const form=$('#invitation-contact');form.elements.stay.onchange=e=>{formDraft=Object.fromEntries(new FormData(form));stayId=e.target.value;linkData=null;draw()};form.oninput=e=>{if(e.target.name!=='confirmed'){form.elements.confirmed.checked=false;linkData=null;$('#invitation-result').textContent=''}};
 form.onsubmit=prepare;
 for(const id of ['doctolib-photo','doctolib-camera'])$('#'+id).onchange=e=>{if(e.target.files[0])loadPhoto(e.target.files[0])};
 $('#doctolib-paste').onpaste=e=>{const image=[...(e.clipboardData?.files||[])].find(f=>f.type.startsWith('image/'));if(image){e.preventDefault();loadPhoto(image)}};
 $('#doctolib-clear').onclick=()=>{clearPhoto();draw()};host.querySelectorAll('[data-line]').forEach(b=>b.onclick=()=>{const f=b.dataset.field,value=C.fieldFromLine(f,readLines[+b.dataset.line]);if(!value){toast(f==='birthDate'?'Aucune date valide sur cette ligne.':'Aucun nom exploitable sur cette ligne.');return}const input=form.elements[f];input.value=value;formDraft=Object.fromEntries(new FormData(form));form.elements.confirmed.checked=false;input.focus();toast('Champ rempli : vérifiez-le sur la photo.')});$('#doctolib-read').onclick=()=>recognize();if(linkData)showLink();
 }
 async function loadPhoto(file){if(busy)return;if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>12*1024*1024){toast('Choisissez une image JPEG, PNG ou WebP de moins de 12 Mo.');return}formDraft={};draft={};linkData=null;clearPhoto();photoUrl=URL.createObjectURL(file);draw();await recognize()}
 async function recognize(){if(!photoUrl||busy)return;busy=true;const expected=++generation;draw();let worker;
 try{
  if(!root.Tesseract)await new Promise((resolve,reject)=>{const script=document.createElement('script');script.src='/ocr/tesseract.min.js';script.onload=resolve;script.onerror=()=>reject(Error('Moteur de lecture indisponible.'));document.head.append(script)});
  const bitmap=await createImageBitmap(await (await fetch(photoUrl)).blob(),{imageOrientation:'from-image'});let step='Préparation de l’image';const show=p=>{const el=$('#doctolib-progress');if(el)el.textContent=step+(p==null?'':' · '+Math.round(p*100)+' %')};show();
  worker=await root.Tesseract.createWorker('fra',1,{workerPath:location.origin+'/ocr/worker.min.js',corePath:location.origin+'/ocr/tesseract-core-lstm.wasm.js',langPath:location.origin+'/ocr',workerBlobURL:false,cacheMethod:'none',logger:m=>{if(m.status==='recognizing text')show(m.progress||0)}});
  const read=await C.readProfile(worker,bitmap,document,(label,i,n)=>{step='Lecture locale '+(i+1)+'/'+n+' · '+label;show(0)});bitmap.close();if(expected!==generation)return;rawText=read.text||read.texts.find(Boolean)||'';readLines=read.profile.lines||[];draft=read.profile;formDraft={};
 }catch(e){loadError(e.message||'Lecture impossible. Renseignez les champs manuellement.')}finally{await worker?.terminate();busy=false;if(expected===generation){draw();const el=$('#doctolib-progress');if(el)el.textContent=rawText?'Lecture terminée. Vérifiez et complétez tous les champs.':'Texte non exploitable : vous pouvez renseigner les champs manuellement.'}}}
 function loadError(message){toast(message);const el=$('#doctolib-progress');if(el)el.textContent=message}
 async function prepare(e){e.preventDefault();if(!ctx.canPrepare()||busy)return;const form=e.currentTarget,v=Object.fromEntries(new FormData(form)),contact=C.contact(v),error=C.contactError(contact);const errorNode=form.querySelector('[role=alert]');if(error){errorNode.textContent=error;return}if(v.confirmed!=='on'){errorNode.textContent='Confirmez la vérification des coordonnées.';return}
 let stay=ctx.patients.find(p=>p.id===v.stay);if(stay?.identity?.lastName&&stay.identity.firstName&&stay.identity.birthDate&&!C.matchesIdentity(stay.identity,contact)){errorNode.textContent='L’identité diffère du séjour sélectionné. Corrigez les champs ou choisissez le bon séjour.';return}
 if(!stay){const duplicate=ctx.patients.find(p=>C.matchesIdentity(p.identity||{},contact));if(duplicate){stayId=duplicate.id;formDraft=contact;draw();$('#invitation-contact [role=alert]').textContent='Un séjour correspond déjà à cette identité. Vérifiez ce séjour puis confirmez à nouveau.';return}if(!v.team){errorNode.textContent='Choisissez une équipe pour le nouveau séjour.';return}stay=ctx.create(contact,v.team);stayId=stay.id;}
 const button=form.querySelector('button.primary');button.disabled=true;
 try{stay.invitationContact={contact,confirmed:true,verifiedBy:ctx.access().profile.user_id,verifiedAt:new Date().toISOString(),source:photoUrl?'Photo Doctolib relue':'Saisie manuelle vérifiée'};await ctx.save();const response=await fetch('/api/workspace/questionnaire/invite',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({stay:stay.id,contact,confirmed:true})});const data=await response.json();if(!response.ok)throw Error(data.error||'Préparation indisponible.');linkData={...data,contact};formDraft=contact;showLink();const channels=autoChannels(contact);if(channels.length)await send(channels);}
 catch(error){errorNode.textContent=error.message}finally{button.disabled=false}
 }
 function showLink(){const out=$('#invitation-result');if(!out||!linkData)return;const {link,expiresAt,contact,results}=linkData,auto=autoChannels(contact),message='Bonjour, merci de remplir votre questionnaire avant votre venue : '+link+'\nLien valable 48 heures, une seule utilisation.';
 const sent=(results||[]).filter(r=>r.sent),failed=(results||[]).filter(r=>!r.sent),label=c=>c==='sms'?'SMS':'E-mail';
 const head=sending?'<h3>Envoi en cours…</h3>':sent.length&&!failed.length&&!sent.some(r=>r.delivery?.state==='failed')?'<h3>Questionnaire envoyé</h3>':sent.length?'<h3>Envoi partiel</h3>':failed.length?'<h3>Envoi impossible</h3>':'<h3>Lien prêt à transmettre</h3>';
 const when=r=>esc(new Date(r.at).toLocaleTimeString('fr-FR',{hour:'2-digit',minute:'2-digit'})),lines=[...sent.map(r=>r.delivery?.state==='failed'?`<p class="notice warn">✗ ${label(r.channel)} parti à ${when(r)} mais non reçu par ${esc(r.to)} : ${esc(r.delivery.reason||'non délivré')}.</p>`:r.delivery?.state==='delivered'?`<p class="notice ok">✓ ${label(r.channel)} reçu par ${esc(r.to)} (envoyé à ${when(r)})</p>`:`<p class="notice ok">✓ ${label(r.channel)} envoyé à ${esc(r.to)} à ${when(r)} · ${r.delivery?.state==='pending'&&r.tries>=4?'pas encore de confirmation de réception':'confirmation de réception en attente…'}</p>`),...failed.map(r=>`<p class="notice warn">✗ ${esc(r.error)}</p>`)].join('');
 out.innerHTML=`${head}${lines}<p>Patient : <strong>${esc(contact.firstName+' '+contact.lastName)}</strong> · ${esc([contact.phone,contact.email].filter(Boolean).join(' · '))}<br><span class="muted">Lien personnel valable jusqu’au ${esc(new Date(expiresAt).toLocaleString('fr-FR'))}, utilisable une seule fois. Le message ne contient que ce lien, sans information médicale.</span></p><div class="actions">${auto.length?`<button class="secondary" id="invitation-resend" ${sending?'disabled':''}>${results?'Renvoyer':'Envoyer'}</button>`:''}<button class="secondary" id="invitation-copy">Copier le message</button><a class="secondary" href="${esc(link)}" target="_blank" rel="noopener noreferrer">Voir le questionnaire</a></div><details><summary>Texte du message</summary><textarea id="invitation-message" rows="4" readonly>${esc(message)}</textarea></details>`;
 const resend=$('#invitation-resend');if(resend)resend.onclick=()=>send(auto);
 $('#invitation-copy').onclick=async()=>{try{await navigator.clipboard.writeText(message);toast('Message copié')}catch{out.querySelector('details').open=true;$('#invitation-message').focus();$('#invitation-message').select();toast('Sélectionnez puis copiez le message.')}};out.scrollIntoView({block:'start',behavior:'smooth'})}
 // Interroge Brevo quelques fois pour afficher si le message est réellement reçu.
 async function trackDelivery(target){for(const wait of [6000,15000,30000,60000]){await new Promise(r=>setTimeout(r,wait));if(linkData!==target)return;const open=(target.results||[]).filter(r=>r.sent&&r.ref&&!['delivered','failed'].includes(r.delivery?.state));if(!open.length)return;
  for(const r of open){try{const q=new URLSearchParams({stay:stayId,channel:r.channel,ref:r.ref});const d=await (await fetch('/api/workspace/messaging/delivery?'+q)).json();r.delivery=d;r.tries=(r.tries||0)+1}catch{}}if(linkData===target&&!sending)showLink()}}
 async function send(channels){if(!linkData||sending)return;sending=true;showLink();
 try{const token=new URLSearchParams(new URL(linkData.link).hash.slice(1)).get('invitation');const response=await fetch('/api/workspace/questionnaire/send',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({stay:stayId,token,channels})});const data=await response.json();if(!data.results)throw Error(data.error||'Envoi indisponible.');linkData.results=data.results;trackDelivery(linkData);toast(data.results.every(r=>r.sent)?'Questionnaire envoyé':'Envoi incomplet : voir le détail')}
 catch(e){linkData.results=[{channel:'',sent:false,error:e.message}]}finally{sending=false;showLink()}}
 window.addEventListener('beforeunload',clearPhoto);return {render};
};
})(typeof window!=='undefined'?window:globalThis);
